j:jelly.script:
      function displayError(msg) {
        gel("error_message").innerHTML = msg;
        gel("error_message_block").style.display = 'inline';
        gel("pwd-close-messages-btn").style.display = 'block';
      }
      function clearError() {
        gel("error_message").innerHTML = '';
        gel("error_message_block").style.display = 'none';
        gel("pwd-close-messages-btn").style.display = 'none';
      }
	  function displayFieldError(field, message, formGroup) {
		fieldElem = gel(field);
		if (fieldElem != undefined) {
			fieldElem.classList.add("icon-alert");
			fieldElem.innerHTML = ' ' + message + '';
			$j("[aria-describedby='" + field + "']").attr('aria-invalid', 'true');
		}
		$j('#' + formGroup).addClass("has-error");
	  }
	  function clearFieldError(field, formGroup) {
		fieldElem = gel(field);
		if (fieldElem != undefined) {
			fieldElem.classList.remove("icon-alert");
			fieldElem.innerHTML = '';
			$j("[aria-describedby='" + field + "']").attr('aria-invalid', 'false');
		}
		$j('#' + formGroup).removeClass("has-error");
	  }
